public class DeckShufflerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> deck = new java.util.ArrayList<>(
                java.util.List.of("AS", "KS", "QS", "JS", "10S"));
        java.util.List<String> result = DeckShuffler.shuffled(deck, 42L);
        check("shuffled(deck, 42)", "[KS, QS, JS, 10S, AS]", String.valueOf(result));
        check("original deck unchanged", "[AS, KS, QS, JS, 10S]", String.valueOf(deck));
        check("returns a new list, not the original", true, result != deck);
        java.util.List<String> colors = new java.util.ArrayList<>(
                java.util.List.of("red", "green", "blue", "yellow"));
        check("shuffled(colors, 1)", "[yellow, red, green, blue]",
                String.valueOf(DeckShuffler.shuffled(colors, 1L)));
        check("colors unchanged", "[red, green, blue, yellow]", String.valueOf(colors));
        check("shuffled(colors, 99)", "[green, red, yellow, blue]",
                String.valueOf(DeckShuffler.shuffled(colors, 99L)));
        check("single-card list", "[solo]",
                String.valueOf(DeckShuffler.shuffled(new java.util.ArrayList<>(java.util.List.of("solo")), 5L)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

